1	// Bech32 test-vector generator. Mirrors the BIP-173 reference exactly, including
2	// the pad=false trailing-group rule `(acc << (tobits - bits)) & maxv`.
3	const CHARSET = 'qpzry9x8gf2tvdw0s3jn54khce6mua7l';
4	const GEN = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3];
5	function polymod(values) { let c = 1; for (const v of values) { const b = c >> 25; c = ((c & 0x1ffffff) << 5) ^ v; for (let i = 0; i < 5; i++) if ((b >> i) & 1) c ^= GEN[i]; } return c; }
6	function hrpExpand(h) { const pts = [...h].map((c) => c.codePointAt(0)); return [...pts.map((p) => p >> 5), 0, ...pts.map((p) => p & 31)]; }
7	function checksum(h, d) { const p = polymod([...hrpExpand(h), ...d, 0, 0, 0, 0, 0, 0]) ^ 1; return [0, 1, 2, 3, 4, 5].map((i) => (p >> (5 * (5 - i))) & 31); }
8	export function convertbits(data, frombits, tobits, pad = true) {
9	  let acc = 0, bits = 0; const ret = []; const maxv = (1 << tobits) - 1, maxAcc = (1 << (frombits + tobits - 1)) - 1;
10	  for (const v of data) { if (v < 0 || v >> frombits) return null; acc = ((acc << frombits) | v) & maxAcc; bits += frombits; while (bits >= tobits) { bits -= tobits; ret.push((acc >> bits) & maxv); } }
11	  if (pad) { if (bits) ret.push((acc << (tobits - bits)) & maxv); } else if (bits >= frombits || ((acc << (tobits - bits)) & maxv)) return null;
12	  return ret;
13	}
14	export function bech32Encode(hrp, data) { return `${hrp}1${[...data, ...checksum(hrp, data)].map((v) => CHARSET[v]).join('')}`; }
15	export function segwitEncode(hrp, witver, prog) { const c = convertbits(prog, 8, 5); return c === null ? null : bech32Encode(hrp, [witver, ...c]); }
16	export { CHARSET };
