1	// Differential runner: replays a corpus of argv arrays against both the Python
2	// executable and the Node port and reports byte-level divergences.
3	// Usage: node diff.mjs corpus.json [maxExamples]
4	import { spawnSync } from 'node:child_process';
5	import { readFileSync } from 'node:fs';
6	
7	const EXE = '/workspace/dataset/test12_executable';
8	const NODE_ENTRY = '/output/test12.mjs';
9	
10	// The two programs legitimately report different prog names in usage/error text
11	// (basename of argv[0], exactly as Python does), so normalise that one token.
12	const normalise = (text) => text.split('test12_executable').join('%PROG%').split('test12.mjs').join('%PROG%');
13	
14	function run(cmd, argv) {
15	  const r = spawnSync(cmd[0], [...cmd.slice(1), ...argv], { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 });
16	  return { out: r.stdout ?? '', err: r.stderr ?? '', code: r.status };
17	}
18	
19	const corpus = JSON.parse(readFileSync(process.argv[2], 'utf8'));
20	const maxExamples = Number(process.argv[3] ?? 8);
21	const mismatches = [];
22	
23	for (const argv of corpus) {
24	  const expected = run([EXE], argv);
25	  const actual = run(['node', NODE_ENTRY], argv);
26	  const same =
27	    normalise(expected.out) === normalise(actual.out) &&
28	    normalise(expected.err) === normalise(actual.err) &&
29	    expected.code === actual.code;
30	  if (!same) mismatches.push({ argv, expected, actual });
31	}
32	
33	console.log(`total=${corpus.length} mismatches=${mismatches.length}`);
34	for (const m of mismatches.slice(0, maxExamples)) {
35	  console.log(JSON.stringify(m));
36	}
