// Corpus generator for the "hrp-charset" family.
// Emits /tmp/corpus/hrp-charset.json : a JSON array of argv arrays.
import { mkdirSync, writeFileSync } from 'node:fs';
import { segwitEncode, bech32Encode, convertbits, CHARSET } from '/tmp/probe/gen.mjs';

const cases = [];
const seen = new Set();
function add(argv) {
  const key = JSON.stringify(argv);
  if (seen.has(key)) return;
  seen.add(key);
  cases.push(argv);
}
function pair(a, b) { add(['--a', a, '--b', b]); }

// A witness program whose bytes are all < 32, so the final convertbits(prog,5,8)
// yields a list rather than None (exercises the printing path too).
const PROG2 = [1, 2];
const PROG20 = Array.from({ length: 20 }, (_, i) => i % 32);
const PROG32 = Array.from({ length: 32 }, (_, i) => (i * 7) % 32);
const PROG40 = Array.from({ length: 40 }, (_, i) => (i * 3) % 32);
const PROGBIG = [200, 31]; // byte >= 32 -> prints None

function enc(hrp, witver, prog) {
  const a = segwitEncode(hrp, witver, prog);
  if (a === null) throw new Error(`enc failed ${hrp}`);
  return a;
}

// ---------------------------------------------------------------- group A
// Every printable ASCII code point 33..126 as a one-character HRP.
const ALL = [];
for (let c = 33; c <= 126; c++) ALL.push(String.fromCharCode(c));
for (const h of ALL) {
  pair(h, enc(h, 1, PROG2));            // -> "1\n[8, 128]\n"
}
for (const h of ALL) {
  pair(h, enc(h, 0, PROG20));           // witver 0, 20-byte program
}

// ---------------------------------------------------------------- group B
// One-char HRPs with an argument that mismatches by one char / prefix / suffix.
for (const h of ALL) {
  const addr = enc(h, 1, PROG2);
  pair(h + h, addr);                    // suffix mismatch
  pair('', addr);                       // empty arg
}

// ---------------------------------------------------------------- group C
// Two-char HRPs across boundary code points.
const BOUND = ['!', '"', '#', '$', '%', '&', "'", '(', ')', '*', '+', ',', '-', '.', '/',
  '0', '1', '9', ':', ';', '<', '=', '>', '?', '@', 'A', 'Z', '[', '\\', ']', '^', '_',
  '`', 'a', 'z', '{', '|', '}', '~'];
for (const x of BOUND) {
  for (const y of ['!', '1', '9', 'a', 'z', '~', '-', 'A']) {
    const h = x + y;
    pair(h, enc(h, 1, PROG2));
  }
}

// ---------------------------------------------------------------- group D
// All-digit HRPs.
const DIGITS = ['0', '1', '2', '9', '00', '01', '10', '11', '19', '91', '99',
  '000', '111', '123', '321', '999', '0123456789', '1010101010', '1111111111',
  '9' .repeat(20), '1'.repeat(40), '1'.repeat(83), '1'.repeat(84), '0'.repeat(83), '0'.repeat(84)];
for (const h of DIGITS) {
  pair(h, enc(h, 1, PROG2));
  pair(h, enc(h, 1, PROG2).toUpperCase());
}

// ---------------------------------------------------------------- group E
// HRPs containing '1' (rfind picks the LAST '1').
const ONES = ['1', '11', '111', 'a1', '1a', 'a1b', 'b1a', '1b1', 'bc1', '1bc', 'x1y1z',
  '1231', 'a1b1c1d', '1'.repeat(10), 'aaa1', '1aaa', 'a'.repeat(41) + '1' + 'a'.repeat(41),
  'a'.repeat(82) + '1', '1' + 'a'.repeat(82), 'a'.repeat(83) + '1', '1' + 'a'.repeat(83)];
for (const h of ONES) {
  pair(h, enc(h, 1, PROG2));
  pair(h, enc(h, 0, PROG20));
}

// ---------------------------------------------------------------- group F
// HRPs drawn entirely from the bech32 data charset.
const CSET = [...CHARSET];
for (const ch of CSET) {
  pair(ch, enc(ch, 1, PROG2));
}
for (const h of [CHARSET, CHARSET.slice(0, 16), CHARSET + CHARSET, CHARSET.repeat(2) + CHARSET.slice(0, 19),
  CHARSET.repeat(2) + CHARSET.slice(0, 20), 'qq', 'll', 'q'.repeat(83), 'l'.repeat(84)]) {
  pair(h, enc(h, 1, PROG2));
}

// ---------------------------------------------------------------- group G
// HRP length boundaries, per filler character.
for (const fill of ['a', '!', '~', '9', 'q', '-', '.', '=', 'z', 'A']) {
  for (const n of [1, 2, 3, 82, 83, 84, 85, 90, 100]) {
    const h = fill.repeat(n);
    pair(h, enc(h, 1, PROG2));
  }
}
// 83-char HRP with a 40-byte program -> total 155 chars, must still decode.
for (const fill of ['a', '!', '~', '9']) {
  for (const n of [83, 84]) {
    const h = fill.repeat(n);
    pair(h, enc(h, 1, PROG40));
    pair(h, enc(h, 0, PROG32));
  }
}

// ---------------------------------------------------------------- group H
// Mismatch by prefix / suffix / one character, against a fixed address.
const BASES = ['bc', 'abcdef', '!', '~', '123', 'a1b', 'q', 'test'];
for (const base of BASES) {
  const addr = enc(base, 1, PROG2);
  const variants = new Set();
  variants.add(base);
  variants.add('');
  variants.add(base.slice(0, -1));            // prefix
  variants.add(base.slice(1));                // suffix drop
  variants.add(base + 'x');                   // suffix add
  variants.add('x' + base);                   // prefix add
  variants.add(base + base);
  variants.add(base.toUpperCase());
  variants.add(base[0].toUpperCase() + base.slice(1));
  variants.add(base + ' ');
  variants.add(' ' + base);
  variants.add(base + '1');
  variants.add('1' + base);
  variants.add([...base].reverse().join(''));
  for (let i = 0; i < base.length; i++) {
    // flip one character to each of a few neighbours
    for (const rep of ['a', 'z', '1', '!', '~', base[i].toUpperCase()]) {
      variants.add(base.slice(0, i) + rep + base.slice(i + 1));
    }
  }
  for (const v of variants) pair(v, addr);
}

// ---------------------------------------------------------------- group I
// HRP arguments that look like option strings.
const OPTISH = ['-', '--', '-h', '--h', '--he', '--hel', '--help', '--a', '--b', '--ab',
  '-5', '-0', '-1', '-1.5', '-.5', '-x', '-5x', '-hh', '-hz', '- 5', ' -x', '=', '==',
  '--a=x', '-a', '-b', '---', '----', '-1p', '-h1'];
const bcAddr = enc('bc', 1, PROG2);
for (const h of OPTISH) {
  pair(h, bcAddr);
  let addr = null;
  try { addr = enc(h, 1, PROG2); } catch { addr = null; }
  if (addr !== null) pair(h, addr);
}

// ---------------------------------------------------------------- group J
// Case handling: upper-case addresses, mixed-case HRPs.
const CASED = ['bc', 'tb', 'ltc', 'BC', 'Bc', 'bC', 'abcdef', 'a1b', 'z', 'Z'];
for (const h of CASED) {
  const addr = enc(h, 1, PROG2);
  pair(h, addr);
  pair(h, addr.toUpperCase());
  pair(h, addr.toLowerCase());
  pair(h.toLowerCase(), addr);
  pair(h.toUpperCase(), addr);
  pair(h.toLowerCase(), addr.toUpperCase());
  pair(h.toUpperCase(), addr.toUpperCase());
  // mixed-case string: HRP upper, data lower
  const pos = addr.lastIndexOf('1');
  const mixed = addr.slice(0, pos).toUpperCase() + addr.slice(pos);
  pair(h, mixed);
  pair(h.toUpperCase(), mixed);
}

// ---------------------------------------------------------------- group K
// Non-printable / non-ASCII HRP characters (the ord<33 / ord>126 gate).
const OUT = ['�', '', '', ' ', '', '', 'é', 'ß',
  'Σ', '€', '😀', '\t', '\n'];
for (const ch of OUT) {
  const h = 'bc' + ch;
  // Build the string by hand: segwitEncode still works, decode must reject.
  const addr = enc(h, 1, PROG2);
  pair(h, addr);
  pair('bc', addr);
  pair(h, bcAddr);
}

// ---------------------------------------------------------------- group L
// Empty payload / short data, with odd HRPs (pos+7 boundary).
for (const h of ['!', '~', '1', 'bc', '9', 'q', '-', 'a'.repeat(83), 'a'.repeat(84)]) {
  const six = bech32Encode(h, []);        // hrp + '1' + 6 checksum chars
  pair(h, six);
  pair(h, six.slice(0, -1));              // 5 data chars -> pos+7 > len
  pair(h, bech32Encode(h, [1]));          // 7 data chars, 0-length program
}

// ---------------------------------------------------------------- group M
// Raw bech32 strings with odd HRPs and payloads that make convertbits fail.
for (const h of ['!', '~', '1', 'bc', '0', 'q', '=', '@', '[', '`']) {
  pair(h, enc(h, 1, PROGBIG));            // -> "1\nNone\n"
  pair(h, enc(h, 16, PROG2));
  pair(h, enc(h, 2, PROG2));
  pair(h, enc(h, 0, PROG32));
  // witver 17 is not encodable via segwitEncode's round-trip check; use raw.
  const c = convertbits(PROG2, 8, 5);
  pair(h, bech32Encode(h, [17, ...c]));
  pair(h, bech32Encode(h, [31, ...c]));
}

// ---------------------------------------------------------------- group N
// One-character difference at every position of a long HRP.
const LONG = 'abcdefgh';
const longAddr = enc(LONG, 1, PROG2);
for (let i = 0; i < LONG.length; i++) {
  for (const rep of ['a', '1', '!', 'H', '~']) {
    pair(LONG.slice(0, i) + rep + LONG.slice(i + 1), longAddr);
  }
  pair(LONG.slice(0, i) + LONG.slice(i + 1), longAddr);   // deletion
  pair(LONG.slice(0, i) + '1' + LONG.slice(i), longAddr); // insertion
}

// ---------------------------------------------------------------- group O
// HRPs at 83/84 that themselves contain '1', plus separator-position probes.
for (const n of [82, 83, 84]) {
  for (const onePos of [0, 1, n - 2, n - 1]) {
    if (onePos < 0 || onePos >= n) continue;
    const h = 'a'.repeat(onePos) + '1' + 'a'.repeat(n - 1 - onePos);
    pair(h, enc(h, 1, PROG2));
  }
}

// ---------------------------------------------------------------- group P
// The --a=<value> form with charset-relevant values.
for (const h of ['bc', '!', '~', '1', '-', '=', 'a=b', '123']) {
  const addr = enc(h, 1, PROG2);
  add([`--a=${h}`, '--b', addr]);
  add([`--a=${h}`, `--b=${addr}`]);
  add(['--a', h, `--b=${addr}`]);
}

mkdirSync('/tmp/corpus', { recursive: true });
writeFileSync('/tmp/corpus/hrp-charset.json', JSON.stringify(cases, null, 0));
console.log(`wrote ${cases.length} cases`);

