// Second, wider sweep for the "hrp-charset" family.
// Emits /tmp/corpus/hrp-charset-2.json
import { mkdirSync, writeFileSync } from 'node:fs';
import { segwitEncode, bech32Encode, convertbits, CHARSET } from '/tmp/probe/gen.mjs';

const cases = [];
const seen = new Set();
function add(argv) {
  const key = JSON.stringify(argv);
  if (seen.has(key)) return;
  seen.add(key);
  cases.push(argv);
}
function pair(a, b) { add(['--a', a, '--b', b]); }

const PROG2 = [1, 2];
const PROG20 = Array.from({ length: 20 }, (_, i) => i % 32);
const PROG32 = Array.from({ length: 32 }, (_, i) => (i * 7) % 32);
const enc = (h, v, p) => segwitEncode(h, v, p);

const ALL = [];
for (let c = 33; c <= 126; c++) ALL.push(String.fromCharCode(c));

// ------------------------------------------------- R: upper-case addresses
// An HRP with no cased characters keeps `upper(s) == s` true for the whole
// upper-cased address, so it is NOT mixed case and must still decode.
for (const h of ALL) {
  const addr = enc(h, 1, PROG2);
  const up = addr.toUpperCase();
  pair(h, up);
  pair(h.toUpperCase(), up);
  // HRP part upper, data part lower -> mixed case unless the HRP has no letters
  const pos = addr.lastIndexOf('1');
  pair(h, addr.slice(0, pos).toUpperCase() + addr.slice(pos));
}

// ------------------------------------------------- S: 83 / 84 for every char
for (const h1 of ALL) {
  for (const n of [83, 84]) {
    const h = h1.repeat(n);
    add(['--a', h, '--b=' + enc(h, 1, PROG2)]);
  }
}

// ------------------------------------------------- T: three-char HRPs
const T = ['!', '-', '.', '/', '0', '1', '9', ':', '=', '?', '@', 'A', 'Z', '[', '\\',
  ']', '^', '_', '`', 'a', 'z', '{', '~', 'q', 'l'];
for (const x of T) {
  for (const y of ['1', 'a', '~']) {
    const h = x + y + x;
    add(['--a', h, '--b=' + enc(h, 1, PROG2)]);
  }
}

// ------------------------------------------------- U: duplicated / reordered flags
const bc = enc('bc', 1, PROG2);
const tb = enc('tb', 1, PROG2);
add(['--a', 'bc', '--a', 'tb', '--b', bc]);
add(['--a', 'bc', '--a', 'tb', '--b', tb]);
add(['--b', bc, '--a', 'bc']);
add(['--b', bc, '--a', '']);
add(['--a=', '--b', '1pqypqdtq4fh']);
add(['--a=', '--b', bc]);
add(['--a', '', '--b', '']);
add(['--a', 'bc', '--b', '']);
add(['--a', '', '--b', '1']);
add(['--a', '1', '--b', '1']);
add(['--a', '1', '--b', '11']);

// ------------------------------------------------- V: one char of the address HRP
// replaced by every other printable code point (checksum breaks -> no output)
const BASE = 'abcd';
const baseAddr = enc(BASE, 1, PROG2);
for (const rep of ALL) {
  for (const i of [0, 3]) {
    const bad = baseAddr.slice(0, i) + rep + baseAddr.slice(i + 1);
    const badHrp = bad.slice(0, bad.lastIndexOf('1'));
    add(['--a', BASE, '--b=' + bad]);
    add(['--a', badHrp, '--b=' + bad]);
  }
}

// ------------------------------------------------- W: address HRP char outside 33..126
for (const cp of [0x01, 0x1f, 0x20, 0x7f, 0x80, 0xa0, 0xff, 0x100, 0x2028, 0xfffd, 0x1f600]) {
  const ch = String.fromCodePoint(cp);
  for (const h of ['bc' + ch, ch + 'bc', ch]) {
    const addr = enc(h, 1, PROG2);
    pair(h, addr);
    pair('bc', addr);
  }
}

// ------------------------------------------------- X: HRP charset x witness version
for (const h of ['!', '~', '0', '1', '=', '`', '\\', '[', ']', '{', '}', '|', '"', "'", '@']) {
  for (const v of [0, 1, 2, 15, 16]) {
    const prog = v === 0 ? PROG20 : PROG2;
    const a = enc(h, v, prog);
    if (a !== null) add(['--a', h, '--b=' + a]);
  }
  const c = convertbits(PROG2, 8, 5);
  for (const v of [17, 20, 31]) {
    add(['--a', h, '--b=' + bech32Encode(h, [v, ...c])]);
  }
  add(['--a', h, '--b=' + enc(h, 0, PROG32)]);
}

// ------------------------------------------------- Y: prefix / suffix ladders
const LADDER = 'abcdefghij';
const ladderAddr = enc(LADDER, 1, PROG2);
for (let n = 0; n <= LADDER.length + 2; n++) {
  add(['--a', LADDER.slice(0, n), '--b=' + ladderAddr]);           // prefixes
  add(['--a', LADDER.slice(n), '--b=' + ladderAddr]);              // suffixes
  add(['--a', LADDER + LADDER.slice(0, n), '--b=' + ladderAddr]);  // extensions
}
const SYM = '!"#$%&\'()*+';
const symAddr = enc(SYM, 1, PROG2);
for (let n = 0; n <= SYM.length; n++) {
  add(['--a', SYM.slice(0, n), '--b=' + symAddr]);
  add(['--a', SYM.slice(n), '--b=' + symAddr]);
}

// ------------------------------------------------- Z: pseudo-random fuzz
let state = 0x2f6e2b1;
function rnd(n) {
  state = (state * 1103515245 + 12345) & 0x7fffffff;
  return state % n;
}
for (let k = 0; k < 500; k++) {
  const len = 1 + rnd(6) === 0 ? 1 : 1 + rnd(90);
  let h = '';
  for (let i = 0; i < len; i++) h += String.fromCharCode(33 + rnd(94));
  const witver = rnd(17);
  const prog = witver === 0
    ? (rnd(2) ? PROG20 : PROG32)
    : Array.from({ length: 2 + rnd(39) }, () => rnd(256));
  const addr = enc(h, witver, prog);
  if (addr === null) continue;
  const mode = rnd(5);
  let a = h;
  if (mode === 1 && h.length > 1) a = h.slice(0, -1);
  else if (mode === 2) a = h + String.fromCharCode(33 + rnd(94));
  else if (mode === 3) a = h.toUpperCase();
  else if (mode === 4 && h.length > 0) {
    const i = rnd(h.length);
    a = h.slice(0, i) + String.fromCharCode(33 + rnd(94)) + h.slice(i + 1);
  }
  add(['--a', a, '--b=' + addr]);
}

mkdirSync('/tmp/corpus', { recursive: true });
writeFileSync('/tmp/corpus/hrp-charset-2.json', JSON.stringify(cases));
console.log(`wrote ${cases.length} cases`);

// Third sweep for "hrp-charset": excluded letters, case folding of symbol HRPs,
// exhaustive 2-char cross products, and raw-string payload boundaries.
// Emits /tmp/corpus/hrp-charset-3.json
import { mkdirSync, writeFileSync } from 'node:fs';
import { segwitEncode, bech32Encode, convertbits, CHARSET } from '/tmp/probe/gen.mjs';

const cases = [];
const seen = new Set();
function add(argv) {
  const k = JSON.stringify(argv);
  if (seen.has(k)) return;
  seen.add(k);
  cases.push(argv);
}
// Always pass the address with `--b=` so a leading '-' never trips argparse.
const P = (a, b) => add(['--a', a, '--b=' + b]);

const PROG2 = [1, 2];
const PROG20 = Array.from({ length: 20 }, (_, i) => i % 32);
const enc = (h, v, p) => segwitEncode(h, v, p);

const ALL = [];
for (let c = 33; c <= 126; c++) ALL.push(String.fromCharCode(c));

// --- AA: every char as the second char of a 2-char HRP, lower + upper address
for (const ch of ALL) {
  for (const first of ['a', 'q', '1', '!', 'Z']) {
    const h = first + ch;
    const addr = enc(h, 1, PROG2);
    P(h, addr);
    P(h, addr.toUpperCase());
    P(h.toUpperCase(), addr.toUpperCase());
    P(h.toLowerCase(), addr.toUpperCase());
  }
}

// --- BB: HRPs made of the letters bech32 EXCLUDES from its data charset
const EXCL = ['b', 'i', 'o', '1', 'bio', 'bio1', '1oib', 'bb', 'ii', 'oo', 'b1i1o',
  'B', 'I', 'O', 'BIO', 'bIo', 'b'.repeat(83), 'i'.repeat(83), 'o'.repeat(83),
  'b'.repeat(84), 'bio'.repeat(28)];
for (const h of EXCL) {
  const addr = enc(h, 1, PROG2);
  P(h, addr);
  P(h, addr.toUpperCase());
  P(h.toUpperCase(), addr.toUpperCase());
  P(h, enc(h, 0, PROG20));
}
// excluded letters injected into the DATA part -> charset rejection
for (const h of ['bc', '!', '1', 'q']) {
  const addr = enc(h, 1, PROG2);
  const pos = addr.lastIndexOf('1');
  for (const bad of ['b', 'i', 'o', 'B', 'I', 'O', '1', '!', ' ', '=']) {
    P(h, addr.slice(0, pos + 1) + bad + addr.slice(pos + 2));
    P(h, addr.slice(0, addr.length - 1) + bad);
  }
}

// --- CC: exhaustive 2-char cross product over a punctuation/digit subset
const S = ['!', '#', '%', '-', '.', '/', '0', '1', '9', ':', '=', '?', '@', '[', '\\',
  ']', '^', '_', '`', '{', '|', '}', '~'];
for (const x of S) {
  for (const y of S) {
    const h = x + y;
    P(h, enc(h, 1, PROG2));
  }
}

// --- DD: symbol-only HRPs with fully upper-cased addresses (no cased chars in
// the HRP, so `upper(s) == s` and the string is not "mixed case")
for (const h of ['!', '!!', '!@#$%^&*()', '0123456789', '-_-', '~~~', '{}', '[]',
  '<>', '|', '\\\\', '``', "''", '""', '=+=', ';:', ',.', '?/', '$#@!']) {
  const addr = enc(h, 1, PROG2);
  P(h, addr);
  P(h, addr.toUpperCase());
  const pos = addr.lastIndexOf('1');
  P(h, addr.slice(0, pos) + addr.slice(pos).toUpperCase());
  P(h, addr.slice(0, pos).toUpperCase() + addr.slice(pos));
}

// --- EE: witness-program length boundaries, per odd HRP
for (const h of ['!', '~', '0', '1', 'q', 'bio', '='.repeat(83)]) {
  for (const n of [1, 2, 3, 20, 32, 39, 40, 41]) {
    const prog = Array.from({ length: n }, (_, i) => i % 32);
    const addr = enc(h, 1, prog);
    if (addr !== null) P(h, addr);
    const addr0 = enc(h, 0, prog);
    if (addr0 !== null) P(h, addr0);
  }
  // raw payload lengths straddling pos+7 and the 5->8 conversion boundary
  for (const n of [0, 1, 2, 3, 4, 5, 6, 7, 8]) {
    P(h, bech32Encode(h, Array.from({ length: n }, (_, i) => i % 32)));
  }
}

// --- FF: strings with no '1', with only '1's, and empty
for (const b of ['', '1', '11', '111', '1111111', '11111111', 'qqqqqq', 'q1', '1q',
  '1qqqqqq', '1qqqqq', 'a1', 'a11', 'a1qqqqqq', 'bc1', 'bc1qqqqq', 'bc1qqqqqq']) {
  for (const a of ['', 'bc', '1', 'a', 'q']) P(a, b);
}

// --- GG: one-character HRP argument perturbations against a symbol address
for (const base of ['!@#', '~~', '0-0', 'a1!']) {
  const addr = enc(base, 1, PROG2);
  for (const rep of ALL) {
    P(base.slice(0, 1) + rep + base.slice(2), addr);
  }
  P(base, addr);
  P(base, addr.toUpperCase());
}

// --- HH: 83/84-char HRPs mixing many code points
function build(n, seedChars) {
  let s = '';
  for (let i = 0; i < n; i++) s += seedChars[i % seedChars.length];
  return s;
}
for (const seed of ['!~', 'a1', '09', 'qQ', '=-', 'bio', '!"#$%&\'()*+,-./', 'AZaz09']) {
  for (const n of [82, 83, 84, 85]) {
    const h = build(n, [...seed]);
    P(h, enc(h, 1, PROG2));
    P(h, enc(h, 1, PROG2).toUpperCase());
  }
}

mkdirSync('/tmp/corpus', { recursive: true });
writeFileSync('/tmp/corpus/hrp-charset-3.json', JSON.stringify(cases));
console.log(`wrote ${cases.length} cases`);
